// Small DOM helpers for the popup and the options page: elements are built
// with the DOM API (never innerHTML), icons from ui/icons.js (Tabler,
// generated by the build), strings from _locales.

import { ICONS } from './icons.js';
import { formatMessage } from '../lib/i18n.js';

const SVG_NS = 'http://www.w3.org/2000/svg';

// The language the user chose in the settings (src/lib/i18n.js), when
// there is one; otherwise the browser's choice among _locales.
let chosen = null; // { lang, messages }

/** Uses a chosen language's catalog from now on (null: the browser's). */
export function useCatalog(catalog) {
  chosen = catalog && catalog.messages ? catalog : null;
}

export function t(key, subs) {
  if (chosen) {
    const s = formatMessage(chosen.messages[key], subs);
    if (s) return s;
  }
  const b = globalThis.browser || globalThis.chrome;
  const s = b && b.i18n ? b.i18n.getMessage(key, subs) : '';
  return s || key;
}

/** The interface language as a BCP 47 tag (the lang attribute, profile labels). */
export function uiLang() {
  if (chosen) return chosen.lang;
  try {
    return (globalThis.browser || globalThis.chrome)?.i18n?.getUILanguage?.() || 'en';
  } catch {
    return 'en';
  }
}

/** el('div', { class: 'x', dataset: { a: 1 } }, child, 'text') */
export function el(tag, attrs = {}, ...children) {
  const node = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs || {})) {
    if (v === undefined || v === null || v === false) continue;
    if (k === 'class') node.className = v;
    else if (k === 'dataset') Object.assign(node.dataset, v);
    else if (k === 'text') node.textContent = v;
    else if (k.startsWith('on') && typeof v === 'function') node.addEventListener(k.slice(2), v);
    else node.setAttribute(k, v === true ? '' : String(v));
  }
  for (const c of children.flat()) {
    if (c === null || c === undefined || c === false) continue;
    node.append(c instanceof Node ? c : document.createTextNode(String(c)));
  }
  return node;
}

/** An outline icon from the Tabler set, coloured by currentColor. */
export function icon(name, cls = 'icon') {
  const svg = document.createElementNS(SVG_NS, 'svg');
  svg.setAttribute('viewBox', '0 0 24 24');
  svg.setAttribute('fill', 'none');
  svg.setAttribute('stroke', 'currentColor');
  svg.setAttribute('stroke-width', '2');
  svg.setAttribute('stroke-linecap', 'round');
  svg.setAttribute('stroke-linejoin', 'round');
  svg.setAttribute('aria-hidden', 'true');
  svg.setAttribute('class', cls);
  for (const [tag, attrs] of ICONS[name] || []) {
    const child = document.createElementNS(SVG_NS, tag);
    for (const [k, v] of Object.entries(attrs)) child.setAttribute(k, v);
    svg.append(child);
  }
  return svg;
}

/** Fills elements carrying data-i18n with their message. */
export function localize(root = document) {
  for (const node of root.querySelectorAll('[data-i18n]')) node.textContent = t(node.dataset.i18n);
  for (const node of root.querySelectorAll('[data-i18n-title]')) node.title = t(node.dataset.i18nTitle);
  document.documentElement.lang = uiLang();
}

export function formatBytes(n, estimated = false) {
  if (!(n > 0)) return t('sizeUnknown');
  const units = ['B', 'KB', 'MB', 'GB'];
  let v = n;
  let i = 0;
  while (v >= 1024 && i < units.length - 1) {
    v /= 1024;
    i++;
  }
  const s = `${v >= 100 || i === 0 ? Math.round(v) : v.toFixed(1)} ${units[i]}`;
  return estimated ? t('sizeAbout', [s]) : s;
}
